<?php namespace AISEO\Activatator; class Activator { public static function run() { global $wpdb; $table=$wpdb->prefix.'ai_seo_logs'; $wpdb->query("CREATE TABLE IF NOT EXISTS $table (id bigint(20) UNSIGNED AUTO_INCREMENT PRIMARY KEY, provider varchar(50), cost decimal(10,4), tokens int, created_at datetime DEFAULT CURRENT_TIMESTAMP)"); update_option('ai_seo_version',AISEO_VERSION); } }
